function mapPoint(id, pair, local = false) {
  return id === 'cargo' && local ? cargoPoint(pair) : pair.slice();
}

function liveFloor(level, x, z) {
  const y = level?.groundHeight?.(x, z);
  return Number.isFinite(y) ? y : null;
