          if (p.x < cx - width / 2 - EPSILON || p.x > cx + width / 2 + EPSILON
            || p.z < cz - depth / 2 - EPSILON || p.z > cz + depth / 2 + EPSILON) continue;
          this._zoneCells[index].push(new RankedZoneCell(face, cell, face.cu * face.cv, i, j));
